// KONTEXT: Baut aus den Tavily-Treffern einen kurzen Text für die KI und merkt sich die erlaubten Quell-Adressen.
// BEISPIEL: 5 Treffer zu "Muster GmbH" werden zu einem Text mit höchstens 6000 Zeichen und einer Liste von 5 Adressen.

// ---------- ABSCHNITT 1: Konstanten ----------
// „Mehr als 6000 Zeichen schicken wir nicht an die KI, das hält die Kosten klein.“
const MAX_ZEICHEN = 6000;

// ---------- ABSCHNITT 2: Treffer einsammeln ----------
// „Wir holen die Trefferliste aus der Antwort von Tavily, sonst eine leere Liste.“
const treffer = $input.first().json.results || [];
// „Wir bauen pro Treffer einen kleinen Textblock mit Adresse, Titel und Inhalt.“
const bloecke = treffer.map((t) => 'QUELLE: ' + t.url + '\nTITEL: ' + t.title + '\nINHALT: ' + t.content);

// ---------- ABSCHNITT 3: Ergebnis zurückgeben ----------
// „Wir geben den gekürzten Text, die erlaubten Adressen und ein Ja/Nein für Treffer weiter.“
return [{ json: { text: bloecke.join('\n\n').slice(0, MAX_ZEICHEN), urls: treffer.map((t) => t.url), hatTreffer: treffer.length > 0 } }];

// KONTEXT: Prüft, ob die KI-Zahlen die Mindestkriterien erfüllen, und gibt nur Größenbänder statt genauer Zahlen zurück.
// BEISPIEL: Umsatz 12,4 Mio. € (Jahr 2023, Quelle bundesanzeiger.de) wird zu "10 bis 50 Mio. €", sonst heißt das Ergebnis keine_zahlen.

// ---------- ABSCHNITT 1: Konstanten ----------
// „Die Zahlen dürfen höchstens 3 Jahre alt sein.“
const MAX_ALTER_JAHRE = 3;
// „Wir merken uns das aktuelle Jahr, um das Alter der Zahlen zu messen.“
const AKTUELLES_JAHR = new Date().getFullYear();

// ---------- ABSCHNITT 2: Eingaben holen ----------
// „Wir holen das Ergebnis der KI, sonst ein leeres Objekt (z. B. wenn es keine Treffer gab).“
const ki = $input.first().json.output || {};
// „Wir holen die erlaubten Quell-Adressen aus dem Schritt davor.“
const erlaubteUrls = $('build_context').first().json.urls || [];

// ---------- ABSCHNITT 3: Mindestkriterien prüfen ----------
// „Wir lesen die Zahlen als Zahl, damit Vergleiche funktionieren.“
const umsatz = Number(ki.umsatzEUR) || 0;
// „Gleiches gilt für die Mitarbeitenden.“
const mitarbeiter = Number(ki.mitarbeiter) || 0;
// „Gleiches gilt für das Jahr der Zahlen.“
const jahr = Number(ki.zahlenJahr) || 0;
// „Kriterium 1: die Firma ist eindeutig gefunden.“
const firmaOk = ki.firmaGefunden === true;
// „Kriterium 2: mindestens eine Zahl und ein Jahr, das nicht zu alt ist.“
const zahlOk = (umsatz > 0 || mitarbeiter > 0) && jahr >= AKTUELLES_JAHR - MAX_ALTER_JAHRE;
// „Kriterium 3: die genannte Quelle stand wirklich in den Suchtreffern.“
const quelleOk = typeof ki.quelleUrl === 'string' && erlaubteUrls.includes(ki.quelleUrl);
// „Kriterium 4: die KI ist sich nicht unsicher.“
const sicherOk = ki.sicherheit !== 'niedrig';

// ---------- ABSCHNITT 4: Ergebnis ----------
// „Wenn ein Kriterium fehlt, melden wir ehrlich keine Zahlen und raten nicht.“
if (!(firmaOk && zahlOk && quelleOk && sicherOk)) {
  // „Wir geben das Ergebnis keine_zahlen mit dem fehlenden Kriterium zurück.“
  return [{ json: { ergebnis: 'keine_zahlen', fehlt: [!firmaOk && 'Firma nicht eindeutig', !zahlOk && 'keine aktuelle Zahl', !quelleOk && 'keine belegbare Quelle', !sicherOk && 'unsicher'].filter(Boolean).join(', ') } }];
}
// „Umsatz in ein Band übersetzen, genaue Zahlen geben wir nicht weiter.“
const umsatzBand = umsatz <= 0 ? 'unbekannt' : umsatz < 1e6 ? 'unter 1 Mio. €' : umsatz < 1e7 ? '1 bis 10 Mio. €' : umsatz < 5e7 ? '10 bis 50 Mio. €' : 'über 50 Mio. €';
// „Mitarbeitende nach den EU-Größenklassen in ein Band übersetzen.“
const mitarbeiterBand = mitarbeiter <= 0 ? 'unbekannt' : mitarbeiter < 10 ? 'unter 10' : mitarbeiter < 50 ? '10 bis 49' : mitarbeiter < 250 ? '50 bis 249' : '250 und mehr';
// „Von der Quelle geben wir nur den Domainnamen weiter.“
const quelle = ki.quelleUrl.replace(/^https?:\/\//, '').split('/')[0];
// „Wir geben das Ergebnis mit Bändern, Jahr und Quelle zurück.“
return [{ json: { ergebnis: 'zahlen', umsatzBand, mitarbeiterBand, jahr, quelle } }];
